static int minLen(int[] a, int target) {
    int best = a.length + 1, s = 0, l = 0;
    for (int r = 0; r < a.length; r++) {
        s += a[r];
        ___ (s >= target) {
            best = Math.min(best, r - l + 1);
            s -= a[l++];
        }
    }
    return best <= a.length ? best : 0;
}

