}

int minLen(const vector<int>& a, int target) {
    int n = a.size(), best = n + 1;
    int s = 0, l = 0;
    for (int r = 0; r < n; r++) {
        s += a[r];
        ___ (s >= target) {
            best = min(best, r - l + 1);
            s -= a[l++];
        }
    }
    return best <= n ? best : 0;
}

def longest_unique(s):
    seen = set()
    l = best = 0
    for r, ch in enumerate(s):
        while ch in seen:
            seen.___(s[l])
            l += 1
        seen.add(ch)
        best = max(best, r - l + 1)
    return best

static int longestUnique(String s) {
    Set<Character> seen = new HashSet<>();
    int l = 0, best = 0;
    for (int r = 0; r < s.length(); r++) {
        char ch = s.charAt(r);
        while (seen.contains(ch))
            seen.___(s.charAt(l++));
        seen.add(ch);
        best = Math.max(best, r - l + 1);
    }
    return best;
}

function longestUnique(s) {
  const seen = new Set();
  let l = 0, best = 0;
  for (let r = 0; r < s.length; r++) {
    while (seen.has(s[r])) seen.___(s[l++]);
    seen.add(s[r]);
    best = Math.max(best, r - l + 1);
  }
  return best;
}

int longestUnique(const string& s) {
    unordered_set<char> seen;
    int l = 0, best = 0;
    for (int r = 0; r < (int)s.size(); r++) {
        while (seen.count(s[r]))
            seen.___(s[l++]);
        seen.insert(s[r]);
        best = max(best, r - l + 1);
    }
    return best;
}
